### 4. Per-User Opt-Out with Offline Support

```kotlin
@Entity(tableName = "user_preferences")
data class UserPreference(
    @PrimaryKey val odId: String,
    val featureId: String,
    val optOut: Boolean,
    val syncStatus: SyncStatus = SyncStatus.PENDING,
    val updatedAt: Long = System.currentTimeMillis()
)

class UserPreferenceRepository(
    private val dao: UserPreferenceDao
) {
    suspend fun setOptOut(userId: String, featureId: String, optOut: Boolean) {
        dao.upsert(UserPreference(
            odId = userId,
            featureId = featureId,
            optOut = optOut,
            syncStatus = SyncStatus.PENDING
        ))
    }

    suspend fun isOptedOut(userId: String, featureId: String): Boolean {
        return dao.getPreference(userId, featureId)?.optOut ?: false
    }

    suspend fun syncPendingChanges() {
        val pending = dao.getPendingSync()
        pending.forEach { pref ->
            try {
                syncToServer(pref)
                dao.updateSyncStatus(pref.odId, SyncStatus.SYNCED)
            } catch (e: Exception) {
                // Keep as PENDING for retry
            }
        }
    }
}
```

### 5. Offline Manifest Caching

```kotlin
@Entity(tableName = "feature_manifest")
data class CachedManifest(
    @PrimaryKey val featureId: String,
    val version: String,
    val downloadUrl: String,
    val sha256Hash: String,
    val sizeBytes: Long,
    val dependencies: String, // JSON array
    val cachedAt: Long,
    val expiresAt: Long
)

class ManifestCacheManager(
    private val dao: ManifestDao,
    private val networkApi: FeatureManifestApi
) {
    suspend fun getManifest(featureId: String): CachedManifest? {
        val cached = dao.getManifest(featureId)
        if (cached != null && !isExpired(cached)) {
            return cached
        }

        // Try network fetch if online
        return try {
            val remote = networkApi.fetchManifest(featureId)
            dao.insert(remote)
            remote
        } catch (e: Exception) {
            // Return stale cache as fallback
            cached?.takeIf { isStaleButUsable(it) }
        }
    }

    private fun isExpired(manifest: CachedManifest): Boolean {
        return System.currentTimeMillis() > manifest.expiresAt
    }
}
```

### 6. Dynamic Module Installation with Rollback

```kotlin
class DynamicModuleInstaller(
    private val splitInstallManager: SplitInstallManager
) {
    private val moduleVersionHistory = mutableMapOf<String, String>()

    suspend fun installModule(
        featureId: String,
        version: String,
        onProgress: (Int) -> Unit
    ): Result<Unit> {
        val sessionParams = SplitInstallSessionParams.Builder()
            .setModuleNames(listOf(featureId))
            .setInstallStrategy(InstallStrategy.IDLE)
            // Defer until charging + WiFi for battery-conscious behavior
            .setRequiresCharging(true)
            .setRequiresWifi(true)
            .build()

        val request = SplitInstallRequest.Builder()
            .addModule(featureId)
            .setSessionParams(sessionParams)
            .build()

        return splitInstallManager.startInstallation(request)
            .addOnSuccessListener { sessionId -> 
                moduleVersionHistory[featureId] = version
                saveVersionHistory()
            }
            .addOnFailureListener { e -> 
                // Rollback handled by Play Store automatically
                // Additional custom rollback:
                performRollback(featureId)
            }
    }

    suspend fun performRollback(featureId: String) {
        // Record rollback in history
        moduleVersionHistory.remove(featureId)
        saveVersionHistory()

        // Uninstall problematic module
        splitInstallManager.deferredUninstall(listOf(featureId))

        // Load fallback UI from base module
        loadFallbackFeature(featureId)
    }

    fun loadFallbackFeature(featureId: String): Fragment {
        return when (featureId) {
            "advanced_analytics" -> AnalyticsFallbackFragment()
            "video_processing" -> VideoFallbackFragment()
            else -> DefaultFallbackFragment()
        }
    }
}
```

### 7. Testing Plan

| Test Type | Approach |
|-----------|----------|
| Unit Tests | Test version compatibility logic, opt-out persistence, manifest caching |
| Integration Tests | Verify ClassLoader isolation, module loading/unloading |
| Instrumented Tests | Test SplitInstallManager flow, feature presence detection |
| Monkey Tests | Validate app stability with dynamic modules loaded/unloaded |
| Offline Tests | Verify manifest cache, opt-out sync queue works without network |
| Rollback Tests | Simulate failed installs, verify fallback UI renders correctly |

### 8. Trade-offs

| Aspect | Trade-off |
|--------|-----------|
| ClassLoader Isolation | Extra memory overhead per module, more complex debugging |
| Offline-First | Stale manifest risk, more local storage used |
| Battery-Conscious | Slower feature availability (waits for WiFi/charging) |
| Rollback | User may experience brief unavailability during rollback |
| Version Compatibility | Maintaining backward compatibility limits refactoring |

The base module should always contain minimal fallback UI/logic for critical features to ensure the app remains functional during module issues.

## Interview Context
This question tests understanding of Android Activity lifecycle fundamentals and proper initialization patterns. Candidates should demonstrate knowledge of state management and recreation scenarios.

## Key Points
- **onCreate()** is always the first lifecycle method called
- **Bundle savedInstanceState** preserves state during activity recreation
- **super.onCreate()** must be called before any other operations
- **setContentView()** should be called early to establish the UI hierarchy
- **One-time initialization** like adapters, listeners, and data loading

## Code Example
```java
@Override
protected void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState); // Must be first
    setContentView(R.layout.activity_main); // UI setup

    // Initialize components
    initializeViews();
    setupListeners();

    // Restore state if available
    if (savedInstanceState != null) {
        restoreData(savedInstanceState);
    }
}
```

